Sql:
SELECT p.ProviderID, p.ProviderName, s.ServiceCode, s.ServiceName, qryProviderServiceEffectiveFiscalYears.MinFiscalYear, qryProviderServiceEffectiveFiscalYears.MaxFiscalYear, psc.RatePerHour, psc.FiscalYear, (SELECT TOP 1 srl.MaxRatePerHour FROM tblServiceRateLimits AS srl WHERE srl.ServiceID = s.ServiceID AND srl.FiscalYear = psc.FiscalYear) AS MaxRatePerHour
FROM (tblServices AS s INNER JOIN (tblProviders AS p INNER JOIN tblProviderServiceCatalog AS psc ON p.ProviderID = psc.ProviderID) ON s.ServiceID = psc.ServiceID) INNER JOIN qryProviderServiceEffectiveFiscalYears ON (psc.ServiceID = qryProviderServiceEffectiveFiscalYears.ServiceID) AND (psc.ProviderID = qryProviderServiceEffectiveFiscalYears.ProviderID)
ORDER BY p.ProviderName, s.ServiceName;
